package com.mediassistrover.backend.service.impl;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.mediassistrover.backend.dto.emergency.request.EmergencyRequests.*;
import com.mediassistrover.backend.dto.emergency.response.EmergencyResponses.*;
import com.mediassistrover.backend.dto.pi.request.PiEnvelope;
import com.mediassistrover.backend.entity.*;
import com.mediassistrover.backend.enums.*;
import com.mediassistrover.backend.exception.*;
import com.mediassistrover.backend.repository.*;
import com.mediassistrover.backend.security.*;
import com.mediassistrover.backend.service.*;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;

@Service @RequiredArgsConstructor @Transactional(readOnly=true)
public class EmergencyServiceImpl implements EmergencyService {
    private final EmergencyIncidentRepository incidentRepository; private final ServiceRequestRepository requestRepository;
    private final RobotRepository robotRepository; private final FacilityMapRepository mapRepository;
    private final EndpointRepository endpointRepository; private final AccountRepository accountRepository;
    private final AlertRepository alertRepository; private final AlertRecipientRepository recipientRepository;
    private final AlertService alertService; private final JobExecutionService jobExecutionService;
    private final JobRepository jobRepository; private final AuditService auditService;
    private final WorkflowRepository workflowRepository;
    private final ObjectMapper objectMapper; private final Clock clock;
    private final OrchestrationWorkService wakeups;
    private final com.mediassistrover.backend.mqtt.MqttWire wire;
    private final com.mediassistrover.backend.validation.WorkflowExecutionReadiness readiness;
    private final com.mediassistrover.backend.validation.DeviceResourceScopePolicy deviceScope;

    @Override @Transactional public SosResponse createSos(PiEnvelope<SosPayload> e,DevicePrincipal actor,RequestMetadata md){
        Robot authenticated=deviceScope.requireCurrentDevice(actor);validateEnvelope(e,actor);
        Robot robot=robotRepository.findByIdForUpdate(authenticated.getRobotId()).orElseThrow(()->new ResourceNotFoundException("Robot not found"));
        if(robot.getDeviceSecretHash()==null||robot.getDeviceTokenVersion()!=actor.tokenVersion()||!robot.getRobotCode().equals(actor.robotCode()))throw new org.springframework.security.access.AccessDeniedException("Device session is no longer valid");
        String key=operationKey(e);ServiceRequest previous=requestRepository.findByIdempotencyKey(key).orElse(null);if(previous!=null)return existing(previous,e);
        SosPayload p=e.payload();if((p.xM()==null)!=(p.yM()==null))throw new BusinessRuleException("xM and yM must both be provided or both be null");FacilityMap map=p.mapId()==null?robot.getCurrentMap():map(p.mapId());Endpoint endpoint=p.endpointId()==null?null:endpoint(p.endpointId());if(endpoint!=null&&(map==null||!endpoint.getMap().getMapId().equals(map.getMapId())))throw new BusinessRuleException("Emergency endpoint must belong to incident map");
        EmergencyIncident incident=incidentRepository.saveAndFlush(EmergencyIncident.builder().robot(robot).map(map).endpoint(endpoint).incidentType("SOS").severity(p.severity()).status(EmergencyIncidentStatus.OPEN).description(p.description()).xM(p.xM()).yM(p.yM()).occurredAt(e.occurredAt()).build());
        ObjectNode data=objectMapper.createObjectNode().put("incident_id",incident.getIncidentId().toString()).put("message",p.description()).put("severity",p.severity().name())
                .put("source_payload_hash",wire.canonicalHash(objectMapper.valueToTree(p)));if(endpoint!=null)data.put("endpoint_id",endpoint.getEndpointId().toString());
        Instant now=Instant.now(clock);ServiceRequest request=requestRepository.saveAndFlush(ServiceRequest.builder().requestedRobot(robot).relatedIncidentId(incident.getIncidentId()).requestCode(code("REQ")).requestType(ServiceRequestType.EMERGENCY_SOS).sourceType(RequestSourceType.ROBOT_UI).priority(p.severity()==EmergencyIncidentSeverity.CRITICAL?100:80).status(ServiceRequestStatus.SUBMITTED).requestNote(p.description()).requestDataJson(data).idempotencyKey(key).requestedAt(now).build());
        Alert alert=alertService.createSystemAlert(key,"SOS",p.severity()==EmergencyIncidentSeverity.CRITICAL?AlertSeverity.CRITICAL:AlertSeverity.WARNING,p.description(),data,incident,request,null,endpoint==null?null:endpoint.getZone(),true,AlertAckPolicy.ANY,now.plusSeconds(300));
        Job job=null;if(robot.getStatus()==RobotStatus.IDLE && jobRepository.findByRobotRobotIdAndStatusIn(robot.getRobotId(),List.of(JobStatus.QUEUED,JobStatus.ACCEPTED,JobStatus.RUNNING,JobStatus.RECOVERY_REQUIRED)).isEmpty()
                && canDispatch(robot)){job=jobExecutionService.createForRequest(request);request.setStatus(ServiceRequestStatus.QUEUED);}else{request.setStatus(ServiceRequestStatus.SUBMITTED);data.put("dispatch_pending",true);}
        auditService.record(null,"EMERGENCY_SOS_CREATED","EmergencyIncident",incident.getIncidentId(),null,Map.of("robotId",robot.getRobotId(),"serviceRequestId",request.getServiceRequestId()),md);return new SosResponse(response(incident),request.getServiceRequestId(),alert.getAlertId(),job==null?null:job.getJobId());
    }
    @Override public DeviceIncidentStatusResponse getDeviceIncident(UUID id,DevicePrincipal actor){EmergencyIncident value=incident(id);deviceScope.requireIncidentOwner(value,actor);ServiceRequest request=requestRepository.findByRelatedIncidentId(id).orElse(null);Alert alert=alertRepository.findByIncidentIncidentId(id).stream().filter(a->"SOS".equals(a.getNotificationType())).min(Comparator.comparing(Alert::getCreatedAt)).orElse(null);Job job=request==null?null:jobRepository.findByServiceRequestServiceRequestId(request.getServiceRequestId()).stream().min(Comparator.comparing(Job::getQueuedAt).thenComparing(Job::getJobId)).orElse(null);return new DeviceIncidentStatusResponse(value.getIncidentId(),value.getRobot().getRobotId(),value.getMap()==null?null:value.getMap().getMapId(),value.getEndpoint()==null?null:value.getEndpoint().getEndpointId(),value.getSeverity(),value.getStatus(),value.getDescription(),value.getXM(),value.getYM(),value.getOccurredAt(),value.getAcknowledgedAt(),value.getResolvedAt(),value.getClosedAt(),request==null?null:request.getServiceRequestId(),request==null?null:request.getStatus(),alert==null?null:alert.getAlertId(),alert==null?null:alert.getStatus(),job==null?null:job.getJobId(),job==null?null:job.getStatus());}
    @Override public IncidentResponse get(UUID id){return response(incident(id));}
    @Override public Page<IncidentResponse> list(EmergencyIncidentStatus status,Pageable p){Page<EmergencyIncident> page=status==null?incidentRepository.findAll(p):incidentRepository.findByStatus(status,p);return page.map(this::response);}
    @Override @Transactional public IncidentResponse acknowledge(UUID id,AccountPrincipal actor,RequestMetadata md){EmergencyIncident i=incident(id);if(i.getStatus()!=EmergencyIncidentStatus.OPEN){if(i.getStatus()==EmergencyIncidentStatus.ACKNOWLEDGED&&i.getAcknowledgedByAccount().getAccountId().equals(actor.accountId()))return response(i);throw new BusinessRuleException("Only OPEN incident can be acknowledged");}Account account=account(actor.accountId());Instant now=Instant.now(clock);for(Alert alert:alertRepository.findByIncidentIncidentId(id))if(alert.getStatus()==AlertStatus.OPEN&&alert.isRequireAck())alertService.acknowledge(alert.getAlertId(),actor,md);i.setStatus(EmergencyIncidentStatus.ACKNOWLEDGED);i.setAcknowledgedByAccount(account);i.setAcknowledgedAt(now);audit(account,"EMERGENCY_ACKNOWLEDGED",i,md);return response(i);}
    @Override @Transactional public IncidentResponse start(UUID id,AccountPrincipal actor,RequestMetadata md){EmergencyIncident i=incident(id);if(i.getStatus()!=EmergencyIncidentStatus.ACKNOWLEDGED)throw new BusinessRuleException("Only ACKNOWLEDGED incident can start handling");if(actor.role()!=Role.ADMIN&&!i.getAcknowledgedByAccount().getAccountId().equals(actor.accountId()))throw new org.springframework.security.access.AccessDeniedException("Incident was acknowledged by another Staff account");i.setStatus(EmergencyIncidentStatus.IN_PROGRESS);audit(account(actor.accountId()),"EMERGENCY_HANDLING_STARTED",i,md);return response(i);}
    @Override @Transactional public IncidentResponse resolve(UUID id,Resolution r,AccountPrincipal actor,RequestMetadata md){EmergencyIncident i=incident(id);if(i.getStatus()!=EmergencyIncidentStatus.IN_PROGRESS)throw new BusinessRuleException("Only IN_PROGRESS incident can be resolved");if(actor.role()!=Role.ADMIN&&!i.getAcknowledgedByAccount().getAccountId().equals(actor.accountId()))throw new org.springframework.security.access.AccessDeniedException("Incident is assigned to another Staff account");Account account=account(actor.accountId());i.setStatus(EmergencyIncidentStatus.RESOLVED);i.setResolvedByAccount(account);i.setResolvedAt(Instant.now(clock));for(Alert a:alertRepository.findByIncidentIncidentId(id))if(a.getStatus()==AlertStatus.ACKNOWLEDGED)a.setStatus(AlertStatus.RESOLVED);auditService.record(account,"EMERGENCY_RESOLVED","EmergencyIncident",id,null,Map.of("status",i.getStatus().name(),"resolutionNote",r.resolutionNote()),md);return response(i);}
    @Override @Transactional public IncidentResponse close(UUID id,AccountPrincipal actor,RequestMetadata md){EmergencyIncident i=incident(id);if(i.getStatus()!=EmergencyIncidentStatus.RESOLVED)throw new BusinessRuleException("Only RESOLVED incident can be closed");i.setStatus(EmergencyIncidentStatus.CLOSED);i.setClosedAt(Instant.now(clock));for(Alert a:alertRepository.findByIncidentIncidentId(id))if(a.getStatus()==AlertStatus.RESOLVED)a.setStatus(AlertStatus.CLOSED);audit(account(actor.accountId()),"EMERGENCY_CLOSED",i,md);return response(i);}
    @Override @Transactional public IncidentResponse falseAlarm(UUID id,Resolution r,AccountPrincipal actor,RequestMetadata md){EmergencyIncident i=incident(id);if(!Set.of(EmergencyIncidentStatus.OPEN,EmergencyIncidentStatus.ACKNOWLEDGED).contains(i.getStatus()))throw new BusinessRuleException("Only OPEN or ACKNOWLEDGED incident can be marked false alarm");Account account=account(actor.accountId());if(i.getAcknowledgedByAccount()!=null&&actor.role()!=Role.ADMIN&&!i.getAcknowledgedByAccount().getAccountId().equals(actor.accountId()))throw new org.springframework.security.access.AccessDeniedException("Incident is assigned to another Staff account");i.setStatus(EmergencyIncidentStatus.FALSE_ALARM);i.setResolvedByAccount(account);i.setResolvedAt(Instant.now(clock));i.setClosedAt(i.getResolvedAt());for(Alert a:alertRepository.findByIncidentIncidentId(id))a.setStatus(AlertStatus.CLOSED);requestRepository.findByRelatedIncidentId(id).ifPresent(request->{request.setStatus(ServiceRequestStatus.CANCELLED);request.setCancelledAt(i.getResolvedAt());for(Job j:jobRepository.findByServiceRequestServiceRequestId(request.getServiceRequestId()))if(!Set.of(JobStatus.SUCCEEDED,JobStatus.FAILED,JobStatus.CANCELLED).contains(j.getStatus())){j=jobRepository.lockById(j.getJobId()).orElseThrow();if(j.isBeOrchestrated()){j.setCancelRequestedAt(i.getResolvedAt());j.setCancelRequestedByAccount(account);wakeups.request(j);}else{j.setStatus(JobStatus.CANCELLED);j.setEndedAt(i.getResolvedAt());}}});auditService.record(account,"EMERGENCY_FALSE_ALARM","EmergencyIncident",id,null,Map.of("reason",r.resolutionNote()),md);return response(i);}
    private SosResponse existing(ServiceRequest request,PiEnvelope<SosPayload> e){if(request.getRequestType()!=ServiceRequestType.EMERGENCY_SOS||request.getRequestedRobot()==null||!request.getRequestedRobot().getRobotId().equals(e.robotId()))throw new ConflictException("SOS operation key belongs to another request");if(request.getRequestDataJson().has("source_payload_hash") && !request.getRequestDataJson().path("source_payload_hash").asText().equals(wire.canonicalHash(objectMapper.valueToTree(e.payload()))))throw new ConflictException("SOS operation key reused with different payload");EmergencyIncident i=incident(request.getRelatedIncidentId());Alert a=alertRepository.findByOperationKey(operationKey(e)).orElseThrow();Job j=jobRepository.findByServiceRequestServiceRequestId(request.getServiceRequestId()).stream().findFirst().orElse(null);return new SosResponse(response(i),request.getServiceRequestId(),a.getAlertId(),j==null?null:j.getJobId());}
    private void validateEnvelope(PiEnvelope<?> e,DevicePrincipal actor){if(!"1.0".equals(e.protocolVersion())||!"EMERGENCY_SOS".equals(e.messageType()))throw new BusinessRuleException("Invalid SOS protocol or messageType");if(!actor.robotId().equals(e.robotId()))throw new BusinessRuleException("Envelope robotId does not match device token");if(e.jobId()!=null||e.jobStepId()!=null)throw new BusinessRuleException("SOS request must not specify jobId/jobStepId");if(e.occurredAt().isAfter(Instant.now(clock).plusSeconds(300)))throw new BusinessRuleException("occurredAt is too far in the future");}
    private String operationKey(PiEnvelope<?> e){UUID hash=UUID.nameUUIDFromBytes(e.operationKey().getBytes(StandardCharsets.UTF_8));return "SOS:"+e.robotId()+":"+hash;}
    private boolean canDispatch(Robot robot){var workflow=workflowRepository.findFirstByServiceTypeIgnoreCaseAndStatusAndAcceptsNewJobsTrueOrderByVersionNoDesc("EMERGENCY",WorkflowStatus.PUBLISHED).orElse(null);if(workflow==null || !readiness.acceptsRobot(workflow,robot))return false;try{readiness.requireReady(workflow);return true;}catch(BusinessRuleException ex){return false;}}
    private IncidentResponse response(EmergencyIncident i){return new IncidentResponse(i.getIncidentId(),i.getRobot()==null?null:i.getRobot().getRobotId(),i.getMap()==null?null:i.getMap().getMapId(),i.getEndpoint()==null?null:i.getEndpoint().getEndpointId(),i.getAcknowledgedByAccount()==null?null:i.getAcknowledgedByAccount().getAccountId(),i.getResolvedByAccount()==null?null:i.getResolvedByAccount().getAccountId(),i.getIncidentType(),i.getSeverity(),i.getStatus(),i.getDescription(),i.getXM(),i.getYM(),i.getOccurredAt(),i.getAcknowledgedAt(),i.getResolvedAt(),i.getClosedAt(),i.getRowVersion());}
    private void audit(Account account,String action,EmergencyIncident i,RequestMetadata md){auditService.record(account,action,"EmergencyIncident",i.getIncidentId(),null,Map.of("status",i.getStatus().name()),md);}
    private String code(String prefix){return prefix+"-"+UUID.randomUUID().toString().replace("-","").substring(0,20).toUpperCase(Locale.ROOT);}private EmergencyIncident incident(UUID id){return incidentRepository.findById(id).orElseThrow(()->new ResourceNotFoundException("EmergencyIncident not found: "+id));}private Robot robot(UUID id){return robotRepository.findById(id).orElseThrow(()->new ResourceNotFoundException("Robot not found: "+id));}private FacilityMap map(UUID id){return mapRepository.findById(id).orElseThrow(()->new ResourceNotFoundException("Map not found: "+id));}private Endpoint endpoint(UUID id){return endpointRepository.findById(id).orElseThrow(()->new ResourceNotFoundException("Endpoint not found: "+id));}private Account account(UUID id){return accountRepository.findById(id).orElseThrow(()->new ResourceNotFoundException("Account not found: "+id));}
}
